    rows={pr for pr,pc in cs}; cols_={pc for pr,pc in cs}
    typ='V' if len(rows)>1 else 'H'
    if typ=='V': fc=list(cols_)[0]; sp=(min(rows),max(rows))
    else:       fc=list(rows)[0]; sp=(min(cols_),max(cols_))
    return typ,fc,sp
def f(inp):
    H,W=len(inp),len(inp[0])
    bg=Counter(x for r in inp for x in r).most_common(1)[0][0]
    comps=components(inp,bg)
    bars=[(col,cs) for col,cs in comps if len(cs)>=2]
    mks=[(col,list(cs)[0]) for col,cs in comps if len(cs)==1]
    out=[row[:] for row in inp]
    infos={}
    for idx,(col,cs) in enumerate(bars):
        infos[idx]=binfo(cs)
    n=len(infos)
    def draw(row_or_col,coord):
        # paint full line at given coord, skipping any bar cells
        for r_ in range(H):
            for c_ in range(W):
                if (r_==row_or_col and 0<=c_<W) and out[r_][c_]==bg: out[r_][c_]=6
        return None
    # helper to paint a row or column skipping bar cells
    def paint_line(coord, horiz=True):
        cells=[(r_,c_) for r_ in range(H) for c_ in range(W)]
        barcells={(p,q) for col,cs in comps if len(cs)>=2 for p,q in cs}
        for (r_,c_) in cells:
            if horiz and r_==coord and (r_,c_) not in barcells: out[r_][c_]=6
            elif not horiz and c_==coord and (r_,c_) not in barcells: out[r_][c_]=6
    for mcol,(mr,mc_) in mks:
        out[mr][mc_]=4
        my=None
        for i in range(n):
            t,fc,sp=infos[i]
            if t=='V' and sp[0]<=mr<=sp[1]: my=i; break
            if t=='H' and sp[0]<=mc_<=sp[1]: my=i; break
        if my is None: continue
        ob=infos[my]
        oth=[k for k,v in infos.items() if k!=my][0]
        ot=infos[oth]
        t,fc,sp=ob
        rel=mr-sp[0] if t=='V' else mc_-sp[0]
        if rel==0: rel=1  # avoid degenerate overlap with other bar (edge case)
        if t=='V':
            for p in range(min(fc,mr)+1,max(fc,mr)): out[mr][p]=6
            rr=ot[2]+rel
            for cc in range(W):
                if out[rr][cc]==bg: out[rr][cc]=6
        else:
            for p in range(min(fc,mr)+1,max(fc,mr)): out[p][mc_]=6
            cs=ot[2]+rel
            for r2 in range(H):
                if out[r2][cs]==bg: out[r2][cs]=6
    return out
for n in ('1','2'):
    print(n, f(G[f'Demo pair {n} input'])==G[f'Demo pair {n} output'])
